def build_mobile_locres(data, replacements=None):
    replacements=MOBILE_TEXT if replacements is None else replacements
    if not isinstance(replacements,dict) or any(
        key not in MOBILE_TEXT or not isinstance(text,str) or '\0' in text
        for key,text in replacements.items()
    ):
        raise ValueError('only approved mobile locres keys and valid text are allowed')
    parsed=read_locres(data)
    r=Reader(data);r.pos=17
    string_offset=r.unpack('<Q');r.unpack('<I');namespace_count=r.unpack('<I')
    entries={}
    for _ in range(namespace_count):
        namespace=r.key()['text']
        for _ in range(r.unpack('<I')):
            key=r.key()['text'];r.unpack('<I')
            name=namespace+'/'+key
            if name in entries:
                raise ValueError('duplicate locres namespace/key')
            entries[name]=(r.pos,r.unpack('<i'))
    if not replacements.keys()<=entries.keys():
        raise ValueError('approved mobile key is missing from input locres')
    count=r.unpack('<I');strings=[];references=[];reference_offsets=[]
    for _ in range(count):
        strings.append(r.string());reference_offsets.append(r.pos);references.append(r.unpack('<i'))
    existing={}
    for index,text in enumerate(strings):
        existing.setdefault(text,index)
    changes=[]
    for name,text in replacements.items():
        position,old=entries[name]
        if strings[old]==text:
            continue
        if text not in existing:
            encoded=(text+'\0').encode('utf-16-le')
            if len(encoded)//2>1_000_000:
                raise ValueError('replacement FString is too long')
            existing[text]=len(strings);strings.append(text);references.append(0)
        new=existing[text]
        references[old]-=1;references[new]+=1
        changes.append((position,new))
    if not changes:
        return data
    if len(strings)>parsed['entry_count']:
        raise ValueError('appended string table exceeds original entry count')
    output=bytearray(data)
    for position,index in changes:
        struct.pack_into('<i',output,position,index)
    struct.pack_into('<I',output,string_offset,len(strings))
    for index,position in enumerate(reference_offsets):
        struct.pack_into('<i',output,position,references[index])
    for index in range(count,len(strings)):
        encoded=(strings[index]+'\0').encode('utf-16-le')
        output+=struct.pack('<i',-len(encoded)//2)+encoded+struct.pack('<i',references[index])
    result=bytes(output)
    read_locres(result)
    return result


if __name__=='__main__':
    directory=Path(__file__).resolve().parent/'research'
    original=(directory/'VR4_patch_en_original.locres').read_bytes()
    if hashlib.sha256(original).hexdigest()!=ORIGINAL_SHA256:
        raise ValueError('original locres SHA256 differs from verified input')
    output=build_mobile_locres(original)
    path=directory/'mobile_VR4.locres';path.write_bytes(output)
    print(f'{path}: {len(MOBILE_TEXT)} approved keys, {len(output)} bytes, sha256={hashlib.sha256(output).hexdigest()}')
